import fs from 'node:fs';
import { gunzipSync } from 'node:zlib';
fs.mkdirSync('dist', { recursive: true });
const files = JSON.parse(gunzipSync(Buffer.from('', 'base64')));
for (const [name, data] of Object.entries(files)) fs.writeFileSync('dist/' + name, Buffer.from(data, 'base64'));
console.log('Built ' + Object.keys(files).length + ' static files');
// Content update 2k26-11-07: registrations open (Microsoft Forms link), fee Rs. 300 per team, 2+2+2 team rule, School of Sciences x IIC, Aditya students only, organiser contact.
fs.writeFileSync('dist/index.html', Buffer.from('', 'base64'));
fs.writeFileSync('dist/challenges.html', Buffer.from('', 'base64'));
fs.writeFileSync('dist/rounds.html', Buffer.from('', 'base64'));
fs.writeFileSync('dist/registration.html', Buffer.from('', 'base64'));
const b = '<button class="motion-toggle" id="motion-toggle" type="button" aria-pressed="false">Motion on</button>'; for (const f of ['index.html', 'challenges.html', 'rounds.html', 'registration.html']) { const p = 'dist/' + f; fs.writeFileSync(p, fs.readFileSync(p, 'utf8').replace(b, '')) } let p = 'dist/registration.html', r = fs.readFileSync(p, 'utf8'); r = r.replace('<div><span>Registration deadline</span><strong>________________</strong></div>', '<div><span>Registration deadline</span><strong>5 December 2k26</strong></div>'); fs.writeFileSync(p, r); p = 'dist/app.js'; let a = fs.readFileSync(p, 'utf8'); for (const s of ["el('motion-toggle').setAttribute('aria-pressed',String(off));", "el('motion-toggle').textContent=off?'Motion off':'Motion on';", "el('motion-toggle').addEventListener('click',()=>setMotion(!motionOff));"]) a = a.replace(s, ''); fs.writeFileSync(p, a);
